-- RAW HAIRS security phase. This migration is source-only until deliberately
-- applied to a reviewed staging database; it is not run by this task.

-- ---------------------------------------------------------------------------
-- 1) Persistent server-side rate limits. Keys are HMACs generated by the API;
--    the database never stores admin email, payment references, or client IPs.
-- ---------------------------------------------------------------------------
create table if not exists public.api_rate_limits (
  key_hash text primary key check (key_hash ~ '^[0-9a-f]{64}$'),
  window_started_at timestamptz not null,
  hit_count integer not null check (hit_count >= 0),
  updated_at timestamptz not null default now()
);
create index if not exists api_rate_limits_updated_idx on public.api_rate_limits(updated_at);
alter table public.api_rate_limits enable row level security;
revoke all on public.api_rate_limits from public, anon, authenticated, service_role;

create or replace function public.consume_api_rate_limit(
  p_key_hash text,
  p_limit integer,
  p_window_seconds integer
)
returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_hits integer;
  v_started timestamptz;
  v_expired boolean;
  v_retry integer;
begin
  if p_key_hash is null or p_key_hash !~ '^[0-9a-f]{64}$'
     or p_limit is null or p_limit < 1 or p_limit > 1000
     or p_window_seconds is null or p_window_seconds < 1 or p_window_seconds > 86400 then
    return jsonb_build_object('allowed', false, 'error', 'invalid_limit');
  end if;

  insert into public.api_rate_limits as current_limit (key_hash, window_started_at, hit_count, updated_at)
  values (p_key_hash, now(), 1, now())
  on conflict (key_hash) do update set
    window_started_at = case
      when current_limit.window_started_at + make_interval(secs => p_window_seconds) <= now() then now()
      else current_limit.window_started_at
    end,
    hit_count = case
      when current_limit.window_started_at + make_interval(secs => p_window_seconds) <= now() then 1
      else current_limit.hit_count + 1
    end,
    updated_at = now()
  returning hit_count, window_started_at into v_hits, v_started;

  v_expired := v_started + make_interval(secs => p_window_seconds) <= now();
  v_retry := greatest(1, ceil(extract(epoch from (v_started + make_interval(secs => p_window_seconds) - now())))::integer);
  delete from public.api_rate_limits where updated_at < now() - interval '1 day';

  return jsonb_build_object(
    'allowed', v_hits <= p_limit,
    'remaining', greatest(0, p_limit - v_hits),
    'retry_after_seconds', case when v_hits > p_limit and not v_expired then v_retry else 0 end
  );
end $$;
revoke all on function public.consume_api_rate_limit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.consume_api_rate_limit(text, integer, integer) to service_role;

create or replace function public.clear_api_rate_limit(p_key_hash text)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  if p_key_hash ~ '^[0-9a-f]{64}$' then
    delete from public.api_rate_limits where key_hash = p_key_hash;
  end if;
end $$;
revoke all on function public.clear_api_rate_limit(text) from public, anon, authenticated;
grant execute on function public.clear_api_rate_limit(text) to service_role;

-- ---------------------------------------------------------------------------
-- 2) Delivery OTP hardening. OTP metadata is kept in a private table so riders
--    cannot mutate lockout/expiry fields through the ordinary rider_jobs RLS
--    update path. Existing SHA-256 codes are accepted only until their short
--    compatibility expiry; new codes use cryptographic randomness + bcrypt.
-- ---------------------------------------------------------------------------
create table if not exists public.rider_otp_controls (
  job_id uuid primary key references public.rider_jobs(id) on delete cascade,
  expires_at timestamptz,
  failed_attempts integer not null default 0 check (failed_attempts >= 0),
  locked_at timestamptz,
  updated_at timestamptz not null default now()
);
alter table public.rider_otp_controls enable row level security;
revoke all on public.rider_otp_controls from public, anon, authenticated;
grant select on public.rider_otp_controls to service_role;

insert into public.rider_otp_controls(job_id, expires_at, failed_attempts, updated_at)
select id,
  case when status in ('assigned', 'picked_up', 'in_transit') then now() + interval '24 hours'
       else coalesce(updated_at, created_at) + interval '24 hours' end,
  0, now()
  from public.rider_jobs where delivery_otp_hash is not null
on conflict (job_id) do nothing;

create or replace function public.assign_rider_job(p_job_id uuid, p_rider_email text)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_rider uuid;
  v_job public.rider_jobs;
  v_otp text;
  v_random_bytes bytea;
  v_random bigint;
begin
  if v_role <> 'service_role' and not (select public.is_raw_hairs_owner()) then
    return jsonb_build_object('ok', false, 'error', 'owner_only');
  end if;
  if coalesce(length(trim(p_rider_email)), 0) < 5 or length(trim(p_rider_email)) > 254 then
    return jsonb_build_object('ok', false, 'error', 'rider_not_found');
  end if;
  select id into v_rider from auth.users where lower(email) = lower(trim(p_rider_email));
  if v_rider is null then return jsonb_build_object('ok', false, 'error', 'rider_not_found'); end if;

  select * into v_job from public.rider_jobs where id = p_job_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'job_not_found'); end if;
  if v_job.status <> 'unassigned' then return jsonb_build_object('ok', false, 'error', 'job_in_progress'); end if;

  v_random_bytes := extensions.gen_random_bytes(4);
  v_random := get_byte(v_random_bytes, 0)::bigint * 16777216
            + get_byte(v_random_bytes, 1)::bigint * 65536
            + get_byte(v_random_bytes, 2)::bigint * 256
            + get_byte(v_random_bytes, 3)::bigint;
  v_otp := lpad((v_random % 1000000)::text, 6, '0');

  update public.rider_jobs
     set rider_id = v_rider, status = 'assigned',
         delivery_otp_hash = extensions.crypt(v_otp, extensions.gen_salt('bf', 12)),
         updated_at = now()
   where id = p_job_id;
  insert into public.rider_otp_controls(job_id, expires_at, failed_attempts, locked_at, updated_at)
  values (p_job_id, now() + interval '24 hours', 0, null, now())
  on conflict (job_id) do update set expires_at = excluded.expires_at,
    failed_attempts = 0, locked_at = null, updated_at = now();
  return jsonb_build_object('ok', true, 'job_id', p_job_id, 'rider_id', v_rider, 'otp', v_otp);
end $$;
revoke all on function public.assign_rider_job(uuid, text) from public, anon, authenticated;
grant execute on function public.assign_rider_job(uuid, text) to service_role;

create or replace function public.unassign_rider_job(p_job_id uuid)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_job public.rider_jobs;
begin
  if v_role <> 'service_role' and not (select public.is_raw_hairs_owner()) then
    return jsonb_build_object('ok', false, 'error', 'owner_only');
  end if;
  select * into v_job from public.rider_jobs where id = p_job_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'job_not_found'); end if;
  if v_job.status <> 'assigned' then return jsonb_build_object('ok', false, 'error', 'job_in_progress'); end if;
  update public.rider_jobs set rider_id = null, status = 'unassigned', delivery_otp_hash = null, updated_at = now()
   where id = p_job_id;
  delete from public.rider_otp_controls where job_id = p_job_id;
  return jsonb_build_object('ok', true, 'job_id', p_job_id);
end $$;
revoke all on function public.unassign_rider_job(uuid) from public, anon, authenticated;
grant execute on function public.unassign_rider_job(uuid) to service_role;

create or replace function public.reissue_delivery_otp(p_job_id uuid)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_job public.rider_jobs;
  v_control public.rider_otp_controls;
  v_otp text;
  v_random_bytes bytea;
  v_random bigint;
begin
  if v_role <> 'service_role' and not (select public.is_raw_hairs_owner()) then
    return jsonb_build_object('ok', false, 'error', 'owner_only');
  end if;
  select * into v_job from public.rider_jobs where id = p_job_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'job_not_found'); end if;
  if v_job.status <> 'in_transit' then return jsonb_build_object('ok', false, 'error', 'invalid_state'); end if;
  select * into v_control from public.rider_otp_controls where job_id = p_job_id for update;
  if found and coalesce(v_control.failed_attempts, 0) < 5
     and v_control.locked_at is null and v_control.expires_at > now() then
    return jsonb_build_object('ok', false, 'error', 'otp_still_valid');
  end if;

  v_random_bytes := extensions.gen_random_bytes(4);
  v_random := get_byte(v_random_bytes, 0)::bigint * 16777216
            + get_byte(v_random_bytes, 1)::bigint * 65536
            + get_byte(v_random_bytes, 2)::bigint * 256
            + get_byte(v_random_bytes, 3)::bigint;
  v_otp := lpad((v_random % 1000000)::text, 6, '0');
  update public.rider_jobs set delivery_otp_hash = extensions.crypt(v_otp, extensions.gen_salt('bf', 12)), updated_at = now()
   where id = p_job_id;
  insert into public.rider_otp_controls(job_id, expires_at, failed_attempts, locked_at, updated_at)
  values (p_job_id, now() + interval '24 hours', 0, null, now())
  on conflict (job_id) do update set expires_at = excluded.expires_at,
    failed_attempts = 0, locked_at = null, updated_at = now();
  return jsonb_build_object('ok', true, 'job_id', p_job_id, 'otp', v_otp);
end $$;
revoke all on function public.reissue_delivery_otp(uuid) from public, anon, authenticated;
grant execute on function public.reissue_delivery_otp(uuid) to service_role;

create or replace function public.confirm_delivery_otp(p_job_id uuid, p_otp text)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_job public.rider_jobs;
  v_control public.rider_otp_controls;
  v_valid boolean := false;
  v_attempts integer;
begin
  select * into v_job from public.rider_jobs where id = p_job_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'job_not_found'); end if;
  if v_role <> 'service_role' and not (select public.is_raw_hairs_owner())
     and v_job.rider_id is distinct from v_user then
    return jsonb_build_object('ok', false, 'error', 'not_your_job');
  end if;
  if v_job.status <> 'in_transit' then return jsonb_build_object('ok', false, 'error', 'invalid_state'); end if;
  select * into v_control from public.rider_otp_controls where job_id = p_job_id for update;
  if not found or v_control.expires_at is null or v_control.expires_at <= now() then
    return jsonb_build_object('ok', false, 'error', 'otp_expired');
  end if;
  if v_control.locked_at is not null or v_control.failed_attempts >= 5 then
    return jsonb_build_object('ok', false, 'error', 'otp_locked');
  end if;

  if coalesce(p_otp, '') ~ '^[0-9]{6}$' and v_job.delivery_otp_hash is not null then
    if left(v_job.delivery_otp_hash, 4) in ('$2a$', '$2b$', '$2y$') then
      v_valid := extensions.crypt(p_otp, v_job.delivery_otp_hash) = v_job.delivery_otp_hash;
    else
      -- Temporary compatibility for existing SHA-256 hashes; these expire after
      -- the backfilled 24-hour window and are replaced by bcrypt on reassignment.
      v_valid := encode(extensions.digest(p_otp, 'sha256'), 'hex') = v_job.delivery_otp_hash;
    end if;
  end if;
  if not v_valid then
    v_attempts := v_control.failed_attempts + 1;
    update public.rider_otp_controls set failed_attempts = v_attempts,
      locked_at = case when v_attempts >= 5 then now() else null end, updated_at = now()
     where job_id = p_job_id;
    return jsonb_build_object('ok', false, 'error', case when v_attempts >= 5 then 'otp_locked' else 'wrong_otp' end);
  end if;

  update public.rider_jobs set status = 'delivered', updated_at = now() where id = p_job_id;
  update public.orders set status = 'delivered', updated_at = now()
   where id = v_job.order_id and status in ('processing', 'dispatched');
  insert into public.notifications (user_id, channel, event_type, title, body, related_order)
  select o.customer_id, 'whatsapp', 'order_delivered', 'Order delivered',
         'Your order was delivered. Thank you for shopping with RAW HAIRS.', o.id
    from public.orders o where o.id = v_job.order_id and o.customer_id is not null;
  return jsonb_build_object('ok', true, 'status', 'delivered');
end $$;
revoke all on function public.confirm_delivery_otp(uuid, text) from public;
grant execute on function public.confirm_delivery_otp(uuid, text) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 3) Guest tracking: serialize failed email attempts per existing order and
--    return only order/status/items/amounts, never guest name or full address.
-- ---------------------------------------------------------------------------
create table if not exists public.guest_tracking_attempts (
  order_id uuid primary key references public.orders(id) on delete cascade,
  window_started_at timestamptz not null default now(),
  failed_attempts integer not null default 0 check (failed_attempts >= 0),
  request_count integer not null default 0 check (request_count >= 0),
  updated_at timestamptz not null default now()
);
alter table public.guest_tracking_attempts add column if not exists request_count integer not null default 0;
create index if not exists guest_tracking_attempts_updated_idx on public.guest_tracking_attempts(updated_at);
alter table public.guest_tracking_attempts enable row level security;
revoke all on public.guest_tracking_attempts from public, anon, authenticated, service_role;

create or replace function public.begin_guest_tracking_attempt(p_order_id uuid)
returns boolean language plpgsql security definer set search_path = ''
as $$
declare
  v_started timestamptz;
  v_failures integer;
  v_requests integer;
begin
  insert into public.guest_tracking_attempts(order_id, window_started_at, failed_attempts, request_count, updated_at)
  values (p_order_id, now(), 0, 0, now()) on conflict (order_id) do nothing;
  select window_started_at, failed_attempts, request_count into v_started, v_failures, v_requests
    from public.guest_tracking_attempts where order_id = p_order_id for update;
  if v_started <= now() - interval '15 minutes' then
    update public.guest_tracking_attempts set window_started_at = now(), failed_attempts = 0, request_count = 0, updated_at = now()
     where order_id = p_order_id;
    v_failures := 0;
    v_requests := 0;
  end if;
  v_requests := coalesce(v_requests, 0) + 1;
  update public.guest_tracking_attempts set request_count = v_requests, updated_at = now() where order_id = p_order_id;
  return coalesce(v_failures, 0) < 10 and v_requests <= 120;
end $$;
revoke all on function public.begin_guest_tracking_attempt(uuid) from public, anon, authenticated;

create or replace function public.fail_guest_tracking_attempt(p_order_id uuid)
returns void language sql security definer set search_path = ''
as $$
  update public.guest_tracking_attempts set failed_attempts = failed_attempts + 1, updated_at = now()
   where order_id = p_order_id;
$$;
revoke all on function public.fail_guest_tracking_attempt(uuid) from public, anon, authenticated;

create or replace function public.clear_guest_tracking_attempts(p_order_id uuid)
returns void language sql security definer set search_path = ''
as $$
  update public.guest_tracking_attempts set failed_attempts = 0, updated_at = now()
   where order_id = p_order_id;
$$;
revoke all on function public.clear_guest_tracking_attempts(uuid) from public, anon, authenticated;

create or replace function public.public_track_order(p_order_id uuid, p_email text)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_order public.orders;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;

  if v_order.customer_id is not null and v_order.customer_id = auth.uid() then
    return jsonb_build_object(
      'ok', true,
      'order', jsonb_build_object('id', v_order.id, 'status', v_order.status,
        'created_at', v_order.created_at, 'subtotal_kobo', v_order.subtotal_kobo,
        'delivery_fee_kobo', v_order.delivery_fee_kobo, 'total_kobo', v_order.total_kobo,
        'payment_method', v_order.payment_method),
      'items', coalesce((select jsonb_agg(jsonb_build_object('product_name', i.product_name,
        'quantity', i.quantity, 'unit_price_kobo', i.unit_price_kobo) order by i.product_name)
        from public.order_items i where i.order_id = p_order_id), '[]'::jsonb),
      'delivery', coalesce((select jsonb_build_object('status', j.status, 'updated_at', j.updated_at)
        from public.rider_jobs j where j.order_id = p_order_id order by j.created_at desc limit 1), 'null'::jsonb)
    );
  end if;
  if v_order.customer_id is not null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if not public.begin_guest_tracking_attempt(p_order_id) then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if coalesce(length(trim(p_email)), 0) > 254 or coalesce(trim(p_email), '') = ''
     or v_order.guest_email is null or lower(v_order.guest_email) <> lower(trim(p_email)) then
    perform public.fail_guest_tracking_attempt(p_order_id);
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  perform public.clear_guest_tracking_attempts(p_order_id);

  return jsonb_build_object(
    'ok', true,
    'order', jsonb_build_object('id', v_order.id, 'status', v_order.status,
      'created_at', v_order.created_at, 'subtotal_kobo', v_order.subtotal_kobo,
      'delivery_fee_kobo', v_order.delivery_fee_kobo, 'total_kobo', v_order.total_kobo,
      'payment_method', v_order.payment_method),
    'items', coalesce((select jsonb_agg(jsonb_build_object('product_name', i.product_name,
      'quantity', i.quantity, 'unit_price_kobo', i.unit_price_kobo) order by i.product_name)
      from public.order_items i where i.order_id = p_order_id), '[]'::jsonb),
    'delivery', coalesce((select jsonb_build_object('status', j.status, 'updated_at', j.updated_at)
      from public.rider_jobs j where j.order_id = p_order_id order by j.created_at desc limit 1), 'null'::jsonb)
  );
end $$;
revoke all on function public.public_track_order(uuid, text) from public;
grant execute on function public.public_track_order(uuid, text) to anon, authenticated;

create or replace function public.guest_order_receipt(p_order_id uuid, p_email text)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_order public.orders;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found or v_order.customer_id is not null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if not public.begin_guest_tracking_attempt(p_order_id) then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if coalesce(length(trim(p_email)), 0) > 254 or coalesce(trim(p_email), '') = ''
     or v_order.guest_email is null or lower(v_order.guest_email) <> lower(trim(p_email)) then
    perform public.fail_guest_tracking_attempt(p_order_id);
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  perform public.clear_guest_tracking_attempts(p_order_id);

  return jsonb_build_object(
    'ok', true,
    'order', jsonb_build_object('id', v_order.id, 'status', v_order.status,
      'created_at', v_order.created_at, 'subtotal_kobo', v_order.subtotal_kobo,
      'delivery_fee_kobo', v_order.delivery_fee_kobo, 'total_kobo', v_order.total_kobo,
      'payment_method', v_order.payment_method),
    'items', coalesce((select jsonb_agg(jsonb_build_object('product_name', i.product_name,
      'quantity', i.quantity, 'unit_price_kobo', i.unit_price_kobo) order by i.product_name)
      from public.order_items i where i.order_id = p_order_id), '[]'::jsonb),
    'payments', coalesce((select jsonb_agg(jsonb_build_object('status', p.status))
      from public.payments p where p.order_id = p_order_id), '[]'::jsonb)
  );
end $$;
revoke all on function public.guest_order_receipt(uuid, text) from public;
grant execute on function public.guest_order_receipt(uuid, text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4) Checkout and guest input limits enforced in the database as well as API.
-- ---------------------------------------------------------------------------
create or replace function public.reserve_cart_items(p_items jsonb, p_minutes integer default 15)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_item jsonb;
  v_product public.products;
  v_reserved integer;
  v_session uuid := gen_random_uuid();
  v_expires timestamptz;
  v_qty integer;
begin
  if p_items is null or jsonb_typeof(p_items) is distinct from 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;
  if jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 50 then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;
  v_expires := now() + make_interval(mins => least(greatest(coalesce(p_minutes, 15), 1), 15));
  if exists (
    select 1 from jsonb_array_elements(p_items) with ordinality e1(value, ord)
    join jsonb_array_elements(p_items) with ordinality e2(value, ord)
      on e1.value ->> 'product_id' = e2.value ->> 'product_id' and e1.ord <> e2.ord
  ) then return jsonb_build_object('ok', false, 'error', 'duplicate_product'); end if;

  for v_item in select e.value from jsonb_array_elements(p_items) with ordinality e(value, ord) order by e.ord loop
    if coalesce(v_item ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_item ->> 'quantity', '') !~ '^[0-9]{1,3}$' then
      return jsonb_build_object('ok', false, 'error', 'invalid_items');
    end if;
    v_qty := (v_item ->> 'quantity')::int;
    if v_qty <= 0 or v_qty > 99 then return jsonb_build_object('ok', false, 'error', 'invalid_quantity'); end if;

    select * into v_product from public.products
     where id = (v_item ->> 'product_id')::uuid and is_active for update;
    if not found then return jsonb_build_object('ok', false, 'error', 'product_unavailable'); end if;
    select coalesce(sum(quantity), 0) into v_reserved from public.inventory_reservations
     where product_id = v_product.id and released_at is null and expires_at > now();
    if v_product.stock - v_reserved < v_qty then
      return jsonb_build_object('ok', false, 'error', 'insufficient_stock', 'available', greatest(v_product.stock - v_reserved, 0));
    end if;
    insert into public.inventory_reservations(product_id, session_token, quantity, expires_at, customer_id)
    values (v_product.id, v_session, v_qty, v_expires, auth.uid());
  end loop;
  return jsonb_build_object('ok', true, 'session_token', v_session, 'expires_at', v_expires);
end $$;
revoke all on function public.reserve_cart_items(jsonb, integer) from public;
grant execute on function public.reserve_cart_items(jsonb, integer) to anon, authenticated;

create or replace function public.create_order_from_reservation(
  p_session_token uuid, p_customer_name text, p_customer_phone text, p_customer_email text,
  p_delivery_address text, p_delivery_state text, p_delivery_city text,
  p_delivery_instructions text, p_payment_method text
)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_subtotal bigint;
  v_fee bigint;
  v_free_above bigint;
  v_order public.orders;
  v_customer uuid := auth.uid();
  v_min_expiry timestamptz;
begin
  if p_payment_method is null or p_payment_method not in ('paystack', 'bank_transfer') then
    return jsonb_build_object('ok', false, 'error', 'invalid_payment_method');
  end if;
  if length(trim(coalesce(p_customer_name, ''))) not between 2 and 120
     or length(regexp_replace(coalesce(p_customer_phone, ''), '[^0-9]', '', 'g')) not between 7 and 15
     or coalesce(p_customer_phone, '') !~ '^[+0-9(). -]{7,30}$'
     or length(trim(coalesce(p_delivery_address, ''))) not between 5 and 500
     or length(trim(coalesce(p_delivery_state, ''))) > 100
     or length(trim(coalesce(p_delivery_city, ''))) > 100
     or length(trim(coalesce(p_delivery_instructions, ''))) > 500 then
    return jsonb_build_object('ok', false, 'error', 'missing_checkout_details');
  end if;
  if coalesce(trim(p_customer_email), '') <> '' and
     (length(trim(p_customer_email)) > 254 or trim(p_customer_email) !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') then
    return jsonb_build_object('ok', false, 'error', 'invalid_email');
  end if;
  if p_payment_method = 'paystack' and coalesce(trim(p_customer_email), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'email_required_for_paystack');
  end if;
  if p_session_token is null or not exists (select 1 from public.inventory_reservations
      where session_token = p_session_token and released_at is null and order_id is null) then
    return jsonb_build_object('ok', false, 'error', 'reservation_not_found');
  end if;
  if exists (select 1 from public.inventory_reservations where session_token = p_session_token
      and released_at is null and order_id is null and expires_at < now()) then
    update public.inventory_reservations set released_at = now()
     where session_token = p_session_token and released_at is null and order_id is null;
    return jsonb_build_object('ok', false, 'error', 'reservation_expired');
  end if;

  select sum(r.quantity * p.price_kobo) into v_subtotal
    from public.inventory_reservations r join public.products p on p.id = r.product_id
   where r.session_token = p_session_token and r.released_at is null and r.order_id is null
     and r.expires_at > now() and p.is_active;
  if v_subtotal is null or v_subtotal <= 0 then return jsonb_build_object('ok', false, 'error', 'pricing_failed'); end if;
  v_fee := coalesce((select nullif(s.settings ->> 'delivery_fee_default', '')::bigint
    from public.store_settings s where s.id = 'default'), 0);
  v_free_above := coalesce((select nullif(s.settings ->> 'min_order_free_delivery', '')::bigint
    from public.store_settings s where s.id = 'default'), 0);
  if v_free_above > 0 and v_subtotal >= v_free_above then v_fee := 0; end if;
  select min(expires_at) into v_min_expiry from public.inventory_reservations
   where session_token = p_session_token and released_at is null and order_id is null;

  insert into public.orders(customer_id, guest_email, customer_name, customer_phone,
    delivery_address, delivery_state, delivery_city, delivery_instructions,
    payment_method, status, currency, subtotal_kobo, delivery_fee_kobo, total_kobo, stock_reserved_until)
  values (v_customer, case when v_customer is null then lower(trim(p_customer_email)) else null end,
    trim(p_customer_name), trim(p_customer_phone), trim(p_delivery_address),
    nullif(trim(p_delivery_state), ''), nullif(trim(p_delivery_city), ''),
    nullif(trim(p_delivery_instructions), ''), p_payment_method, 'awaiting_payment', 'NGN',
    v_subtotal, v_fee, v_subtotal + v_fee, v_min_expiry) returning * into v_order;
  insert into public.order_items(order_id, product_id, product_name, unit_price_kobo, quantity)
  select v_order.id, r.product_id, p.name, p.price_kobo, r.quantity
    from public.inventory_reservations r join public.products p on p.id = r.product_id
   where r.session_token = p_session_token and r.released_at is null and r.order_id is null;
  update public.inventory_reservations set order_id = v_order.id
   where session_token = p_session_token and released_at is null and order_id is null;
  return jsonb_build_object('ok', true, 'order_id', v_order.id,
    'total_kobo', v_order.total_kobo, 'subtotal_kobo', v_order.subtotal_kobo,
    'delivery_fee_kobo', v_order.delivery_fee_kobo);
end $$;
revoke all on function public.create_order_from_reservation(uuid, text, text, text, text, text, text, text, text) from public;
grant execute on function public.create_order_from_reservation(uuid, text, text, text, text, text, text, text, text) to anon, authenticated;

create or replace function public.submit_bank_transfer_receipt(
  p_order_id uuid, p_sender_name text, p_bank text, p_transfer_reference text
)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_order public.orders;
  v_payment public.payments;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found or (v_order.customer_id is not null and v_order.customer_id is distinct from auth.uid()) then
    return jsonb_build_object('ok', false, 'error', 'not_your_order');
  end if;
  if v_order.status <> 'awaiting_payment' then return jsonb_build_object('ok', false, 'error', 'order_not_payable'); end if;
  if v_order.payment_method <> 'bank_transfer' then return jsonb_build_object('ok', false, 'error', 'order_not_bank_transfer'); end if;
  if length(trim(coalesce(p_sender_name, ''))) not between 2 and 120
     or length(trim(coalesce(p_bank, ''))) not between 2 and 100
     or length(trim(coalesce(p_transfer_reference, ''))) not between 3 and 100 then
    return jsonb_build_object('ok', false, 'error', 'missing_checkout_details');
  end if;
  select * into v_payment from public.payments where order_id = p_order_id and status = 'pending'
   order by created_at desc limit 1 for update;
  if not found then
    insert into public.payments(order_id, payment_method, status, amount_kobo, currency, reference)
    values (p_order_id, 'bank_transfer', 'pending', v_order.total_kobo, 'NGN',
      'BANK-' || substr(replace(p_order_id::text, '-', ''), 1, 12) || '-' || substr(encode(extensions.gen_random_bytes(8), 'hex'), 1, 10))
    returning * into v_payment;
  end if;
  update public.payments set status = 'awaiting_verification', provider = trim(p_bank),
    failure_reason = null, provider_response = jsonb_build_object('sender_name', trim(p_sender_name),
    'bank', trim(p_bank), 'transfer_reference', trim(p_transfer_reference), 'submitted_at', now()), updated_at = now()
   where id = v_payment.id;
  return jsonb_build_object('ok', true, 'payment_id', v_payment.id, 'status', 'awaiting_verification');
end $$;
revoke all on function public.submit_bank_transfer_receipt(uuid, text, text, text) from public;
grant execute on function public.submit_bank_transfer_receipt(uuid, text, text, text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 5) Webhook replay protection while retaining Paystack's legacy HMAC format.
--    A unique verified transaction id and payload hash are committed atomically
--    with the idempotent payment update.
-- ---------------------------------------------------------------------------
create table if not exists public.paystack_webhook_receipts (
  event_type text not null check (event_type = 'charge.success'),
  transaction_id bigint not null check (transaction_id > 0),
  reference text not null,
  payload_sha256 text not null check (payload_sha256 ~ '^[0-9a-f]{64}$'),
  processed_at timestamptz not null default now(),
  primary key (event_type, transaction_id),
  unique (payload_sha256)
);
alter table public.paystack_webhook_receipts enable row level security;
revoke all on public.paystack_webhook_receipts from public, anon, authenticated, service_role;

create or replace function public.mark_payment_successful_from_webhook(
  p_reference text, p_amount_kobo bigint, p_provider_response jsonb,
  p_transaction_id bigint, p_payload_sha256 text
)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_payment public.payments;
  v_inserted bigint;
begin
  if v_role <> 'service_role' then return jsonb_build_object('ok', false, 'error', 'forbidden'); end if;
  if p_reference is null or p_reference !~ '^[A-Za-z0-9._-]{6,100}$'
     or p_amount_kobo is null or p_amount_kobo < 0
     or p_transaction_id is null or p_transaction_id <= 0
     or p_payload_sha256 is null or p_payload_sha256 !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_event');
  end if;

  insert into public.paystack_webhook_receipts(event_type, transaction_id, reference, payload_sha256)
  values ('charge.success', p_transaction_id, p_reference, p_payload_sha256)
  on conflict do nothing returning transaction_id into v_inserted;
  if v_inserted is null then return jsonb_build_object('ok', true, 'status', 'duplicate'); end if;

  select * into v_payment from public.payments where reference = p_reference for update;
  if not found or v_payment.amount_kobo is distinct from p_amount_kobo or v_payment.currency <> 'NGN'
     or v_payment.payment_method <> 'paystack' or v_payment.status not in ('pending', 'successful') then
    delete from public.paystack_webhook_receipts where event_type = 'charge.success' and transaction_id = p_transaction_id;
    return jsonb_build_object('ok', false, 'error', 'payment_not_eligible');
  end if;
  if v_payment.status <> 'successful' then
    update public.payments set status = 'successful',
      provider_response = coalesce(p_provider_response, provider_response), verified_at = now(), updated_at = now()
     where id = v_payment.id;
    update public.orders set status = 'paid', updated_at = now()
     where id = v_payment.order_id and status = 'awaiting_payment';
  end if;
  return jsonb_build_object('ok', true, 'status', 'successful');
end $$;
revoke all on function public.mark_payment_successful_from_webhook(text, bigint, jsonb, bigint, text) from public, anon, authenticated;
grant execute on function public.mark_payment_successful_from_webhook(text, bigint, jsonb, bigint, text) to service_role;

-- Explicit server-only permission for the existing callback verification path.
revoke all on function public.mark_payment_successful(text, bigint, jsonb) from public, anon, authenticated;
grant execute on function public.mark_payment_successful(text, bigint, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 6) Admin order transitions stay in the DB workflow. Delivery cannot be
--    marked delivered here; only the OTP RPC can complete a rider job/order.
-- ---------------------------------------------------------------------------
create or replace function public.advance_order_status(p_order_id uuid, p_new_status text)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_order public.orders;
begin
  if v_role <> 'service_role' and not (select public.is_raw_hairs_owner()) then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  select * into v_order from public.orders where id = p_order_id and status not in ('cancelled', 'refunded') for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'order_not_found'); end if;
  if not (
       (v_order.status = 'pending_admin_approval' and p_new_status = 'processing')
    or (v_order.status = 'paid' and p_new_status = 'processing')
    or (v_order.status = 'processing' and p_new_status = 'dispatched')
    or (v_order.status = 'awaiting_payment' and p_new_status = 'cancelled')
    or (v_order.status = 'pending_admin_approval' and p_new_status = 'cancelled')
    or (v_order.status = 'paid' and p_new_status = 'cancelled')
  ) then return jsonb_build_object('ok', false, 'error', 'invalid_transition'); end if;
  if p_new_status = 'processing' and v_order.status = 'pending_admin_approval'
     and not exists (select 1 from public.payments p where p.order_id = p_order_id and p.status = 'successful') then
    return jsonb_build_object('ok', false, 'error', 'payment_not_successful');
  end if;
  update public.orders set status = p_new_status,
    approved_at = case when v_order.status in ('pending_admin_approval', 'paid') and p_new_status = 'processing' then now() else approved_at end,
    cancelled_at = case when p_new_status = 'cancelled' then now() else cancelled_at end,
    cancel_reason = case when p_new_status = 'cancelled' then 'cancelled_by_owner' else cancel_reason end
   where id = p_order_id;
  if p_new_status = 'cancelled' then
    update public.inventory_reservations set released_at = now() where order_id = p_order_id and released_at is null;
    update public.orders set stock_reserved_until = null where id = p_order_id;
  end if;
  return jsonb_build_object('ok', true, 'order_id', p_order_id, 'status', p_new_status);
end $$;
revoke all on function public.advance_order_status(uuid, text) from public, anon, authenticated;
grant execute on function public.advance_order_status(uuid, text) to service_role;

-- ---------------------------------------------------------------------------
-- 7) Storage-side limits. The API verifies image signatures and dimensions
--    after signed product uploads and before attaching rider evidence.
-- ---------------------------------------------------------------------------
update storage.buckets set file_size_limit = 5242880,
  allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp']
where id = 'product-images';
update storage.buckets set file_size_limit = 8388608,
  allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp']
where id = 'delivery-evidence';
